begin;
create function public.admin_football_quality() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare output jsonb;
begin
 if auth.uid() is null or not public.has_permission('owner.override') then raise exception 'Forbidden';end if;
 select jsonb_build_object('checked_at',now(),'freshness',jsonb_build_object('matches_updated_at',(select max(goal_updated_at) from matches),'players_updated_at',(select max(goal_updated_at) from players),'cache_updated_at',(select max(updated_at) from football_cache),'live_stale',(select count(*) from matches where status='live' and (goal_updated_at is null or goal_updated_at<now()-interval '5 minutes')),'cache_expired',(select count(*) from football_cache where expires_at<now())),'duplicates',jsonb_build_object('fixture_ids',coalesce((select jsonb_agg(t) from (select coalesce(goal_fixture_id,goal_fixture_api_id) as provider_id,count(*) as copies from matches where coalesce(goal_fixture_id,goal_fixture_api_id) is not null group by coalesce(goal_fixture_id,goal_fixture_api_id) having count(*)>1 order by count(*) desc limit 30)t),'[]'::jsonb),'fixtures',coalesce((select jsonb_agg(t) from (select kickoff,home_name,away_name,count(*) as copies from matches group by kickoff,home_club_id,away_club_id,goal_league_id,home_name,away_name having count(*)>1 order by count(*) desc limit 30)t),'[]'::jsonb),'events',coalesce((select jsonb_agg(t) from (select match_id,event_type,minute,team_side,coalesce(to_jsonb(e)->>'player_ref_id',to_jsonb(e)->>'player_id',player_name) as player,count(*) as copies from match_events e group by match_id,event_type,minute,team_side,coalesce(to_jsonb(e)->>'player_ref_id',to_jsonb(e)->>'player_id',player_name) having count(*)>1 order by count(*) desc limit 30)t),'[]'::jsonb)),'coverage',coalesce((select jsonb_agg(t) from (select goal_league_id,competition,goal_league_year as season,count(*) as matches,count(*) filter(where coalesce(goal_fixture_id,goal_fixture_api_id) is not null) as provider_ids,count(*) filter(where exists(select 1 from match_events e where e.match_id=m.id)) as timeline_matches,count(*) filter(where exists(select 1 from football_cache c where c.cache_key='/fixtures/'||coalesce(m.goal_fixture_id,m.goal_fixture_api_id)||'/lineups' and jsonb_path_exists(c.payload,'$.**.startingLineups[*]'))) as lineup_matches,count(*) filter(where exists(select 1 from football_cache c where c.cache_key='/fixtures/'||coalesce(m.goal_fixture_id,m.goal_fixture_api_id)||'/statistics' and (jsonb_path_exists(c.payload,'$.**.fullTime[*]') or case when jsonb_typeof(c.payload)='array' then jsonb_array_length(c.payload)>0 else false end))) as statistics_matches from matches m group by goal_league_id,competition,goal_league_year order by count(*) desc limit 100)t),'[]'::jsonb)) into output;
 return output;
end$$;
revoke all on function public.admin_football_quality() from public,anon;
grant execute on function public.admin_football_quality() to authenticated;
commit;
